// The fixed text line of the recognizer check (recognizer 'auto', src/core/engine.ts): 320 x 48 gray pixels drawn by
// scripts/make-probe.mjs (text "Total ¥8,415 合計 OK", font 28px Hiragino Sans, @napi-rs/canvas 1.0.11). Gray levels 0-15,
// run-length coded: each byte is (run - 1) << 4 | level, level * 17 = the 8-bit gray value. Generated; do not edit.

export const PROBE_TEXT = "Total ¥8,415 合計 OK";
export const PROBE_W = 320;
export const PROBE_H = 48;
const RLE = '';

/** The line as recognizer input of width W (>= 320): BGR, (x - 127.5) / 127.5, zero (normalized) right padding. */
export function probeInput(W: number): Float32Array {
  const bin = atob(RLE);
  const gray = new Uint8Array(PROBE_W * PROBE_H);
  let p = 0;
  for (let i = 0; i < bin.length; i++) {
    const b = bin.charCodeAt(i);
    gray.fill((b & 15) * 17, p, p + (b >> 4) + 1);
    p += (b >> 4) + 1;
  }
  const plane = PROBE_H * W;
  const out = new Float32Array(3 * plane);
  for (let y = 0; y < PROBE_H; y++) {
    for (let x = 0; x < PROBE_W; x++) {
      const v = (gray[y * PROBE_W + x]! - 127.5) / 127.5;
      const t = y * W + x;
      out[t] = v;
      out[plane + t] = v;
      out[2 * plane + t] = v;
    }
  }
  return out;
}
